//! Generated bytes traverse admitted compaction, child copies and authenticated import.
use super::*;
use crate::context::{ContextInput, ContextStage};
use crate::conversation::{BoundedContentFuture, ContentIo, ContentResidencyVerifier, FileRef};
use crate::fork::ForkSeed;
use crate::model::{ModelContent, ModelRole};
use proptest::prelude::*;
use proptest::test_runner::TestCaseResult;

struct Input {
    turns: [String; 2],
    responses: [String; 3],
}

impl Input {
    fn new(text: [String; 5]) -> Self {
        Self {
            turns: std::array::from_fn(|i| format!("input-{i}:{}", text[i])),
            responses: std::array::from_fn(|i| format!("response-{i}:{}", text[i + 2])),
        }
    }

    fn model(&self) -> Arc<ScriptedModelProvider> {
        Arc::new(
            summary_model_turns(self.responses.iter().cloned().map(ScriptedTurn::Text))
                // Charge tiny user files like the original fixture's 60 KB inputs.
                // This admits the same summary without copying redundant padding.
                // All filesystem bytes, checkpoints, copies and grants remain real.
                .with_token_counter(|request| {
                    let counts = request
                        .request()
                        .messages
                        .iter()
                        .map(|message| {
                            let bytes = message
                                .content
                                .file_refs()
                                .map(|file| {
                                    if matches!(
                                        file.display_name(),
                                        "input.txt" | "later-input.txt"
                                    ) {
                                        60_000
                                    } else {
                                        file.descriptor().byte_length()
                                    }
                                })
                                .sum::<u64>();
                            u32::try_from(bytes + 512).map_err(|e| Error::Invalid(e.to_string()))
                        })
                        .collect::<Result<Vec<_>>>()?;
                    Ok(ModelTokenCount::from_upper_bounds(
                        request.request_digest(),
                        512,
                        counts,
                    ))
                }),
        )
    }
}

struct Case {
    parent: StreamAggregate<MemoryStream>,
    child: StreamAggregate<MemoryStream>,
    seed: ForkSeed,
    parent_volume: VolumeRef,
    scope: Scope,
    reader: Arc<dyn ContentResidencyVerifier>,
    limits: Limits,
}

impl Case {
    async fn new(input: &Input) -> Result<Self> {
        let (storage, _, reference, limits) =
            summary_parent_inputs(input.turns.each_ref().map(|s| s.as_bytes()), input.model())
                .await?;
        let aggregate = StreamAggregate::open(
            &storage.stream,
            (
                storage.conversation.clone(),
                storage.verifier(),
                SchemaRegistry::new(),
            ),
            None,
            crate::store::default_projection_read_limits(),
            crate::store::DEFAULT_TERMINAL_EFFECTS,
            None,
            &mut None,
        )
        .await?
        .with_content_verifier(storage.content_verifier.clone());
        let SummaryFixture {
            storage,
            aggregate,
            preparer,
            request,
            scope: parent_scope,
            stream_provider,
            limits,
            ..
        } = summary_fork_fixture(storage, aggregate, reference, limits).await?;
        let (task_preparation, _invocation) =
            sealed_summary_preparation(&storage, &preparer, &request, 1_000_000, 134_217_728)
                .await?;
        let preparer = preparer.with_task_preparation(Arc::new(task_preparation))?;
        let report = aggregate.prepare_fork(&preparer, request).await?;
        let seed = report.into_seed(&mut None)?;
        let parent =
            publish_summary_seed(&storage, aggregate, &seed, parent_scope, &stream_provider)
                .await?;
        let parent_volume = storage.volume.clone();
        let issuer = AuthorityIssuer::new("summary-child", [42; 32], seed.child.clone());
        let grants = Capabilities::new(
            seed.reference_capabilities(seed.child_agent)?
                .iter()
                .map(str::to_owned)
                .chain([
                    "conversation:bind".to_owned(),
                    seed.child_private_volume
                        .capability(VolumeOperation::Read, &mut None)?,
                ]),
        );
        let scope = issuer.issue("child", &grants, Some(seed.child_agent), None, &mut None)?;
        let verifier = issuer.verifier(&mut None)?;
        let reader =
            FilesystemContentVerifier::new(storage.host.clone(), &verifier, &scope, 262_144, None)?;
        let mut child = StreamAggregate::open(
            &storage.stream,
            (seed.child.clone(), verifier, SchemaRegistry::new()),
            None,
            crate::store::default_projection_read_limits(),
            crate::store::DEFAULT_TERMINAL_EFFECTS,
            None,
            &mut None,
        )
        .await?;
        child
            .bind_published_child(&parent, &seed, scope.clone(), None, &mut None)
            .await?;
        Ok(Self {
            parent,
            child,
            seed,
            parent_volume,
            scope,
            reader,
            limits,
        })
    }

    async fn stage(
        &self,
        seed: &ForkSeed,
        reader: Arc<dyn ContentResidencyVerifier>,
    ) -> Result<crate::context::PinnedContextStage> {
        self.child
            .history_reader()?
            .summary_fork_stage(
                &self.parent.history_reader()?,
                seed,
                &self.scope,
                reader,
                self.limits,
                HistoryReadLimits {
                    maximum_events: 2,
                    maximum_bytes: 262_144,
                },
            )
            .await
    }

    async fn read(
        &self,
        seed: &ForkSeed,
        reader: Arc<dyn ContentResidencyVerifier>,
    ) -> Result<Context> {
        let stage = self.stage(seed, reader).await?;
        let input = ContextInput {
            input: ModelContent::Text("fresh child".into()),
            selected_context: None,
            step: 0,
            prior_messages: Vec::new(),
        };
        stage
            .apply(&input, Context::default(), self.limits, None)?
            .await
    }
}

/// Corrupt the real authorized read, preserving canonical JSON and file references.
struct Tampered {
    inner: Arc<dyn ContentResidencyVerifier>,
    target: FileRef,
}
impl ContentResidencyVerifier for Tampered {
    fn read<'a>(
        &'a self,
        reference: &'a FileRef,
        maximum_bytes: u64,
        ceiling: Option<&'a crate::Capabilities>,
        io: Option<&'a ContentIo>,
    ) -> Result<BoundedContentFuture<'a, acyclic_stream::OwnedBytes>> {
        let read = self.inner.read(reference, maximum_bytes, ceiling, io)?;
        BoundedContentFuture::new(io, || async move {
            let bytes = read.await?;
            if reference != &self.target {
                return Ok(bytes);
            }
            let mut context: Context = crate::contract::json_from_slice(&bytes)
                .map_err(|e| Error::Invalid(e.to_string()))?;
            context.messages.swap(0, 1);
            Ok(crate::contract::canonical_json_bytes(&context)?.into())
        })
    }
}

#[derive(Clone, Copy)]
enum Fault {
    None,
    OmitCopy,
    WrongSummary,
    AcceptCut,
    AcceptTamper,
    RejectHealthy,
}

async fn check_round_trip(input: &Input, case: &Case, fault: Fault) -> TestCaseResult {
    let actual = case.read(&case.seed, case.reader.clone()).await;
    let accepted = actual.is_ok() && !matches!(fault, Fault::RejectHealthy);
    prop_assert!(accepted, "healthy summary import rejected");
    let mut context = actual.unwrap();
    if matches!(fault, Fault::OmitCopy) {
        context.messages.remove(0);
    }
    let mut messages = Vec::new();
    let mut copied = context.current_input_index.is_none() && context.metadata.is_empty();
    for (index, message) in context.messages.iter().enumerate() {
        let mut bytes = Vec::new();
        for file in message.content.file_refs() {
            let expected_volume = if index == 0 {
                &case.seed.child_private_volume
            } else {
                &case.parent_volume
            };
            copied &= file.volume() == expected_volume;
            bytes.extend_from_slice(
                &case
                    .reader
                    .read(file, 262_144, None, None)
                    .unwrap()
                    .await
                    .unwrap(),
            );
        }
        messages.push((message.role, bytes));
    }
    if matches!(fault, Fault::WrongSummary) {
        messages[0].1 = input.responses[0].as_bytes().to_vec();
    }
    // The admitted checkpoint predates answer 2. Require its exact summary and
    // retained input followed by the complete canonical tail (sequence 4).
    let expected = [
        (ModelRole::Assistant, input.responses[1].as_bytes().to_vec()),
        (ModelRole::User, input.turns[1].as_bytes().to_vec()),
        (ModelRole::Assistant, input.responses[2].as_bytes().to_vec()),
    ];
    prop_assert!(
        copied && messages == expected,
        "summary copies or frozen cut differ from input bytes: copied={}, actual={:?}, expected={:?}",
        copied,
        messages,
        expected
    );

    let mut changed = case.seed.clone();
    changed.inherited_through_sequence -= 1;
    let submitted = if matches!(fault, Fault::AcceptCut) {
        &case.seed
    } else {
        &changed
    };
    let rejected = case.stage(submitted, case.reader.clone()).await.is_err();
    prop_assert!(rejected, "summary cut mismatch accepted");

    let target = case.seed.summary.as_ref().unwrap().context.clone();
    let reader = if matches!(fault, Fault::AcceptTamper) {
        case.reader.clone()
    } else {
        Arc::new(Tampered {
            inner: case.reader.clone(),
            target,
        })
    };
    let rejected = case.stage(&case.seed, reader).await.is_err();
    prop_assert!(rejected, "tampered summary bytes accepted");
    Ok(())
}

proptest! {
    #![proptest_config(ProptestConfig::with_cases(32))]
    #[test]
    fn generated_capture_publication_and_authenticated_read(
        text in prop::array::uniform5("[a-z0-9\\x00é🦀]{0,8}"),
    ) {
        let runtime = tokio::runtime::Builder::new_current_thread().enable_all().build().unwrap();
        let input = Input::new(text);
        runtime.block_on(async {
            let case = Case::new(&input).await.unwrap();
            check_round_trip(&input, &case, Fault::None).await
        })?;
    }
}

fn detected(result: TestCaseResult, target: &str) {
    let failure = result.unwrap_err();
    assert!(failure.to_string().contains(target), "{failure}");
}

#[tokio::test]
async fn capture_and_read_negative_controls() {
    let input = Input::new(std::array::from_fn(|_| String::new()));
    let case = Case::new(&input).await.unwrap();
    check_round_trip(&input, &case, Fault::None).await.unwrap();
    for (fault, target) in [
        (
            Fault::OmitCopy,
            "summary copies or frozen cut differ from input bytes",
        ),
        (
            Fault::WrongSummary,
            "summary copies or frozen cut differ from input bytes",
        ),
        (Fault::AcceptCut, "summary cut mismatch accepted"),
        (Fault::AcceptTamper, "tampered summary bytes accepted"),
        (Fault::RejectHealthy, "healthy summary import rejected"),
    ] {
        detected(check_round_trip(&input, &case, fault).await, target);
    }
}
